class Solution:
    def checkArray(self, nums: List[int], k: int) -> bool:
        arr = [0] * (len(nums) + 1)
        h = 0
        i = 0

        while i < len(nums):
            n = nums[i]
            h -= arr[i]

            if n > h:
                if i + k > len(nums):
                    return False
                else:
                    arr[i + k] = n - h
            elif n < h:
                return False
            else:
                h = n
            i += 1

        return True

