class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        nums = nums.copy()
        ops = 0
        total = 0
        last_skipped = -1

        if sum(nums) < target:
            return -1

        nums.sort()

        while True:
            i = len(nums) - 1
            total = 0
            last_skipped = -1

            while i >= 0:
                if total + nums[i] > target:
                    last_skipped = i
                    i -= 1
                else:
                    total += nums[i]
                    i -= 1

            if total == target:
                return ops

            if last_skipped == -1:
                break

            new = nums.pop(last_skipped) // 2
            nums.append(new)
            nums.append(new)
            ops += 1

