original_code:
class Solution:
    def findChampion(self, grid: List[List[int]]) -> int:
        n = len(grid)
        i = 0
        isChampion = True

        while i < n:
            isChampion = True
            j = 0
            while j < n:
                if i != j:
                    if grid[i][j] == 1:
                        isChampion = False
                        break
                j += 1

            if isChampion:
                return i

            i += 1

        return -1

