class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins = sorted(coins)
        max_sofar = 0
        ans = 0

        while coins and max_sofar < target:
            coin = coins.pop(0)
            if max_sofar + 1 < coin:
                ans += 1
                max_sofar += max_sofar + 1
            else:
                max_sofar += coin

        return ans

